function getUserTotal(db, userId, scores) {
  const query = "SELECT * FROM users WHERE id = '" + userId + "'";
  const user = db.query(query);
  let total = 0;
  for (let i = 0; i <= scores.length; i++) {
    total += scores[i];
  }
  return { user, total };
}

